from rdkit import Chem
m=Chem.MolFromMolFile('optimized.mol',removeHs=False)
lines=open('answer.xyz').readlines(); assert int(lines[0])==len(lines)-2==m.GetNumAtoms(); print('atom count:',len(lines)-2,'elements:',{el:sum(a.GetSymbol()==el for a in m.GetAtoms()) for el in ('C','O','H')});print('xyz comment',lines[1].strip())
from rdkit.Geometry import Point3D
c=m.GetConformer();
for idx,l in enumerate(lines[2:]):
 el,x,y,z=l.split(); assert el==m.GetAtomWithIdx(idx).GetSymbol();c.SetAtomPosition(idx, Point3D(float(x),float(y),float(z)))
for a in m.GetAtoms():a.SetChiralTag(Chem.ChiralType.CHI_UNSPECIFIED)
Chem.AssignAtomChiralTagsFromStructure(m,replaceExistingTags=True)
Chem.AssignStereochemistry(m,force=True,cleanIt=True)
for a in m.GetAtoms():
 if a.HasProp('_CIPCode'):print(a.GetIdx(),a.GetProp('_CIPCode'))
print('size',len(open('answer.xyz').read()))
